<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$posts=(array)($inbox['posts']??[]);$conversations=(array)($inbox['conversations']??[]);$access=(array)($inbox['message_access']??[]);?>
<style>.inbox-toolbar{display:flex;gap:8px;align-items:end}.inbox-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:12px;margin-top:12px}.inbox-list{display:grid;gap:7px}.inbox-item{padding:11px;border:1px solid #e4eaf0;border-radius:10px;background:#fff}.inbox-meta{display:flex;justify-content:space-between;gap:8px;color:#718197;font-size:11px}.inbox-origin{margin:6px 0;padding:7px 9px;border-left:2px solid #8cb9dd;background:#f7fafc;color:#536b82;font-size:11px}.inbox-item p{margin:7px 0;white-space:pre-wrap}.inbox-link{color:#28699f;font-size:11px;text-decoration:none}.inbox-reply{display:flex;gap:6px;margin-top:7px}.inbox-reply textarea{flex:1;min-height:42px;padding:8px}.inbox-reply .button{padding:7px 10px}.inbox-access{display:flex;gap:7px;flex-wrap:wrap;margin:8px 0}.inbox-access span{padding:4px 7px;border-radius:7px;background:#f1f4f7;font-size:10px}.inbox-access .ok{background:#e9f6ef;color:#23745a}.inbox-access .bad{background:#fff0f0;color:#a44750}@media(max-width:900px){.inbox-grid{grid-template-columns:1fr}}</style>
<section class="panel"><div class="panel-head"><div><h2>Messages et commentaires</h2><p class="panel-subtitle">Échanges récents des Pages Facebook connectées.</p></div><form method="get" class="inbox-toolbar"><label>Page<select name="connection_id" onchange="this.form.submit()"><option value="">Choisir</option><?php foreach($connections as$c):?><option value="<?= (int)$c['id']?>" <?= (int)$selected===(int)$c['id']?'selected':''?>><?= $e($c['account_label'])?></option><?php endforeach?></select></label></form></div></section>
<?php if($error):?><div class="flash error"><?= $e($error)?></div><?php endif?>
<div class="inbox-grid"><section class="panel"><h2>Commentaires</h2><div class="inbox-list"><?php if(!$posts):?><p>Aucun commentaire récent.</p><?php endif?><?php foreach($posts as$post):foreach((array)($post['comments']['data']??[])as$comment):$commentLink=trim((string)($post['permalink_url']??''));if($commentLink!=='')$commentLink.=(str_contains($commentLink,'?')?'&':'?').'comment_id='.urlencode((string)preg_replace('/^.*_/','',(string)($comment['id']??'')));?><article class="inbox-item"><div class="inbox-meta"><strong><?= $e($comment['from']['name']??'Auteur non communiqué par Meta')?></strong><span><?= $e(!empty($comment['created_time'])?date('d/m/Y H:i',strtotime($comment['created_time'])):'')?></span></div><div class="inbox-origin">Page : <?= $e($inbox['connection']['account_label']??'')?> · Publication : <?= $e(mb_strimwidth((string)($post['message']??'Sans texte'),0,120,'…'))?></div><p><?= $e($comment['message']??'')?></p><?php if($commentLink!==''):?><a class="inbox-link" href="<?= $e($commentLink)?>" target="_blank" rel="noopener">Voir sur Facebook ↗</a><?php endif?><?php if($canReply):?><form method="post" action="<?= $e(route_url('/social-inbox/reply-comment'))?>" class="inbox-reply"><input type="hidden" name="connection_id" value="<?= (int)$selected?>"><input type="hidden" name="comment_id" value="<?= $e($comment['id']??'')?>"><textarea name="message" required placeholder="Répondre…"></textarea><button class="button" type="submit">Envoyer</button></form><?php endif?></article><?php endforeach;endforeach?></div></section>
<section class="panel"><h2>Messages privés</h2><div class="inbox-access"><span class="<?= !empty($access['scope_granted'])?'ok':'bad'?>">pages_messaging <?= !empty($access['scope_granted'])?'accordée':'absente du jeton'?></span><span class="<?= !empty($access['task_granted'])?'ok':'bad'?>">Tâche MESSAGING <?= !empty($access['task_granted'])?'présente':'absente'?></span></div><?php if(!empty($inbox['message_error'])):?><div class="flash info"><?= $e($inbox['message_error'])?> <a href="<?= $e(route_url('/social-oauth/connect/'.(int)$selected))?>">Réactualiser les accès Meta ↗</a></div><?php endif?><div class="inbox-list"><?php if(!$conversations):?><p>Aucune conversation récente.</p><?php endif?><?php foreach($conversations as$conversation):$participants=(array)($conversation['participants']['data']??[]);$recipient='';foreach($participants as$p)if((string)($p['id']??'')!==(string)($inbox['connection']['external_account_id']??'')){$recipient=(string)$p['id'];break;}?><article class="inbox-item"><?php foreach(array_reverse((array)($conversation['messages']['data']??[]))as$message):?><div class="inbox-meta"><strong><?= $e($message['from']['name']??'Utilisateur')?></strong><span><?= $e(!empty($message['created_time'])?date('d/m/Y H:i',strtotime($message['created_time'])):'')?></span></div><p><?= $e($message['message']??'')?></p><?php endforeach?><?php if($canReply&&$recipient!==''):?><form method="post" action="<?= $e(route_url('/social-inbox/reply-message'))?>" class="inbox-reply"><input type="hidden" name="connection_id" value="<?= (int)$selected?>"><input type="hidden" name="recipient_id" value="<?= $e($recipient)?>"><textarea name="message" required placeholder="Répondre…"></textarea><button class="button" type="submit">Envoyer</button></form><?php endif?></article><?php endforeach?></div></section></div>
